import React, { useState } from "react";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");

  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [clinicalTrials, setClinicalTrials] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async () => {
    if (!disease.trim() && !intent.trim()) return;

    try {
      setLoading(true);
      setError("");

      const res = await fetch("http://localhost:5000/api/query", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          disease,
          intent,
          location
        })
      });

      if (!res.ok) throw new Error("Search request failed");

      const data = await res.json();

      setSummary(data.summary || "");
      setPublications(data.publications || []);
      setClinicalTrials(data.clinical_trials || []);

    } catch (err) {
      console.error(err);
      setError("Failed to fetch medical research data.");
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadPDF = async () => {
    try {
      const query = `${disease} ${intent} ${location}`.trim();

      const res = await fetch("http://localhost:8000/generate-pdf", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          query,
          summary,
          publications,
          clinical_trials: clinicalTrials
        })
      });

      if (!res.ok) throw new Error("PDF generation failed");

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);

      const link = document.createElement("a");
      link.href = url;
      link.download = "medical_report.pdf";

      document.body.appendChild(link);
      link.click();
      link.remove();

      window.URL.revokeObjectURL(url);

    } catch (err) {
      console.error("PDF Download Failed:", err);
      alert("PDF download failed.");
    }
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>AI Medical Research Assistant</h1>

      <p style={styles.subheading}>
        Search medical literature, clinical trials, and generate AI-powered summaries instantly.
      </p>

      <div style={styles.searchBox}>
        <input
          type="text"
          placeholder="Disease / Condition"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
          style={styles.input}
        />

        <input
          type="text"
          placeholder="Additional Query / Intent"
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
          style={styles.input}
        />

        <input
          type="text"
          placeholder="Location (Optional)"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          style={styles.input}
        />

        <button onClick={handleSubmit} style={styles.button}>
          {loading ? "Searching..." : "Search"}
        </button>
      </div>

      {error && <p style={styles.error}>{error}</p>}

      {(publications.length > 0 || clinicalTrials.length > 0) && (
        <button onClick={handleDownloadPDF} style={styles.pdfButton}>
          Download Research Report PDF
        </button>
      )}

      {summary && (
        <div style={styles.summaryBox}>
          <h2>AI Summary</h2>
          <p>{summary}</p>
        </div>
      )}

      {publications.length > 0 && (
        <>
          <h2 style={styles.sectionTitle}>Research Publications</h2>

          <div style={styles.results}>
            {publications.map((pub, index) => (
              <div key={index} style={styles.card}>
                <h3>{pub.title}</h3>

                <p style={styles.meta}>
                  {pub.authors?.join(", ")}
                  {pub.year ? ` • ${pub.year}` : ""}
                </p>

                <p>{pub.abstract || "No abstract available."}</p>

                <a href={pub.link} target="_blank" rel="noreferrer" style={styles.link}>
                  View Full Publication →
                </a>
              </div>
            ))}
          </div>
        </>
      )}

      {clinicalTrials.length > 0 && (
        <>
          <h2 style={styles.sectionTitle}>Clinical Trials</h2>

          <div style={styles.results}>
            {clinicalTrials.map((trial, index) => (
              <div key={index} style={styles.card}>
                <h3>{trial.title}</h3>

                <p style={styles.meta}>
                  Phase: {trial.phase || "N/A"}
                </p>

                <a href={trial.link} target="_blank" rel="noreferrer" style={styles.link}>
                  View Clinical Trial →
                </a>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

const styles = {
  container: {
    minHeight: "100vh",
    padding: "40px",
    fontFamily: "Inter, Arial, sans-serif",
    background: "linear-gradient(135deg, #eef2ff 0%, #f8fafc 100%)"
  },

  heading: {
    fontSize: "42px",
    fontWeight: "800",
    textAlign: "center",
    marginBottom: "12px",
    color: "#0f172a"
  },

  subheading: {
    textAlign: "center",
    color: "#475569",
    marginBottom: "35px",
    fontSize: "18px"
  },

  searchBox: {
    display: "grid",
    gap: "12px",
    marginBottom: "30px",
    background: "rgba(255,255,255,0.7)",
    backdropFilter: "blur(12px)",
    padding: "18px",
    borderRadius: "18px",
    boxShadow: "0 8px 30px rgba(0,0,0,0.08)"
  },

  input: {
    padding: "16px",
    fontSize: "16px",
    borderRadius: "12px",
    border: "1px solid #dbeafe",
    outline: "none"
  },

  button: {
    padding: "16px 26px",
    background: "linear-gradient(135deg, #2563eb, #1d4ed8)",
    color: "white",
    border: "none",
    borderRadius: "12px",
    cursor: "pointer",
    fontWeight: "700"
  },

  pdfButton: {
    padding: "14px 24px",
    background: "linear-gradient(135deg, #16a34a, #15803d)",
    color: "white",
    border: "none",
    borderRadius: "12px",
    cursor: "pointer",
    fontWeight: "700",
    marginBottom: "30px"
  },

  summaryBox: {
    background: "white",
    padding: "24px",
    borderRadius: "18px",
    marginBottom: "30px",
    boxShadow: "0 10px 25px rgba(0,0,0,0.06)",
    borderLeft: "6px solid #2563eb"
  },

  sectionTitle: {
    marginTop: "40px",
    marginBottom: "20px",
    fontSize: "28px",
    fontWeight: "700",
    color: "#0f172a"
  },

  results: {
    display: "grid",
    gap: "22px"
  },

  card: {
    background: "white",
    padding: "26px",
    borderRadius: "18px",
    boxShadow: "0 10px 25px rgba(0,0,0,0.06)"
  },

  meta: {
    color: "#64748b",
    fontSize: "14px",
    marginBottom: "12px"
  },

  link: {
    display: "inline-block",
    marginTop: "14px",
    color: "#2563eb",
    textDecoration: "none",
    fontWeight: "700"
  },

  error: {
    color: "#dc2626",
    marginBottom: "20px",
    fontWeight: "600"
  }
};

export default App;
